assert m.paint(w2)==0 and m.selected(w2)==5 and m.get(w2+O['SCROLL_Y'])==204
assert m.sel()==(0,36,240,48)
assert m.confirm()==11 and m.dispatched()[0][1]==es2[5]; passed()
