m.paint(w,gap=0); assert m.sel()==(0,42,240,48)
assert m.call(gap=O['EDGE_PAUSE_MS']-1)==11 and m.selected(w)==5   # re-armed, not wrapped
assert m.call(gap=O['EDGE_PAUSE_MS'])==11 and m.selected(w)==0
passed()

