            m=LookupMachine(['home_page','playing_page']+pages,selected,lookup)
            w=m.node('button',f'{button}_{selected}'); m.word(w+0x10,m.string(f'{button}_{selected}'))
            m.word(w+0x78,selected); m.word(m.event+0x10,w)
