def bar_setup(light='1',state=0,name='Balance'):
    db=LoadPlain(); db.config.update(THEME='1',LIGHT=light); classic_light_boot(db)
    if state: db.handlers.pop(syms['mclGetPlayStatus'],None); db.word(0xa50084,state)
