CONFIG.clear(); CONFIG.update(THEME='1',LIGHT='0')
def cue(m):  # the slider's paint: the ink's rows
    m.bands.clear(); m.call(address=HOOKS['widget_on_paint_border'][0],args=(m.slider,m.canvas,0,0),gap=0)
