m=app_lrc('app:3:2',body=b'\xef\xbb\xbfPlain\nwords\n'); assert m.load()==1 and m.lines==[(FAR,'Plain'),(FAR,'words')],m.lines; passed()
m=app_lrc('app:2:2'); assert m.load()==-1 and not m.lines; passed()  # an older queue's track
