import scenarios.coverflow_tags

# Albums grids and Folder view (GRID_COVER): stock's embedded art first; ffmpeg only for an Ogg track
# stock found none in, never for an MP3 or FLAC, run with parse_cover_mutex dropped. It writes dst.ff,
# renamed onto dst only when non-empty (an empty one, left on exit 0, is removed and dst kept); waitpid
# is retried on EINTR; a miss is remembered, so the track's next row forks nothing. The Albums grid's
# call reads the folder image (toolsGetExternCover) before ffmpeg, which then never runs for it.
from build import GRID_COVER
for call,_,fn in GRID_COVER:
    assert struct.unpack_from('<I',demo,fileoff(demo,call))[0]==jal(payload_syms[fn])
m=GridCoverMachine()
for track,found in (('01.opus',1),('01.mp3',0),('01.flac',0),('opus',0)):
    assert m.cover(track,found=found)==found and m.seen==['toolsGetAlbumCover'],(track,m.seen)
m.files={m.dst:b'old'}
assert m.cover('01.OGG')==0 and m.seen==['toolsGetAlbumCover','calloc','pthread_mutex_unlock','fork','unlink',
                                         'pthread_mutex_lock'],m.seen  # fork refused: not a miss
assert m.cover('01.OGG')==0 and 'fork' in m.seen,m.seen  # so the next request tries again
assert m.cover('02.opus',out=b'')==0 and m.files=={m.dst:b'old'} and m.seen.count('waitpid')==2,(m.files,m.seen)
assert m.cover('02.opus',out=b'')==0 and m.seen==['toolsGetAlbumCover'],m.seen  # the miss is remembered
assert m.cover('03.opus',out=b'jpeg')==1 and m.files=={m.dst:b'jpeg'} and 'toolsGetExternCover' not in m.seen
assert m.seen.index('pthread_mutex_unlock')<m.seen.index('fork')<m.seen.index('pthread_mutex_lock')
assert m.cover('04.opus','coverflow_album_cover',extern=1)==1 and m.seen==['toolsGetAlbumCover','toolsGetExternCover']
assert m.cover('05.opus','coverflow_album_cover',extern=0)==1 and 'fork' in m.seen
passed()
# Folder view's folder row (coverflow_folder_cover): stock asks for each song in directory order (the order
# they were copied) until one has art; the folder's first song by name, as Folder view lists it, is tried
# first: a regular file (or one of unknown type) with the extension of stock's, whatever its case, and no
# dot file (a Mac's ._ copies). Through the walk the folder isn't listed again and its first song, without
# art, isn't tried twice; a hit ends the walk, and the next one lists the folder again. A path too long to
# keep, or with no extension, goes to stock as it is.
m=FolderCoverMachine(); A='/mnt/mmc/Музыка/Альбом'
m.scope_tree={A:[('05 Five.flac',8),('04 Four.flac',8),('cover.jpg',8),('00 Intro.mp3',8),('CD2',4),
                 ('._01 One.flac',0),('01 One.FLAC',0),('02 Two.flac',8)]}
m.art={A+'/01 One.FLAC',A+'/04 Four.flac'}
assert m.folder(A+'/05 Five.flac')==1 and m.tried==[A+'/01 One.FLAC'],m.tried
m.scope_tree[A].append(('00 Zero.flac',8)); m.art.add(A+'/00 Zero.flac')
assert m.folder(A+'/05 Five.flac')==1 and m.tried==[A+'/00 Zero.flac']  # the next walk lists again
far='/mnt/mmc/'+'x'*600+'/1.flac'; m.art.add(far)
assert m.folder(far)==1 and m.tried==[far]  # too long to keep: stock's song alone
assert m.folder('/mnt/mmc/Vol.2/notes')==0 and m.tried==['/mnt/mmc/Vol.2/notes']
m.art={A+'/04 Four.flac'}
assert m.folder(A+'/05 Five.flac')==0 and m.tried==[A+'/00 Zero.flac',A+'/05 Five.flac']
m.scope_tree[A].append(('0 New.flac',8)); m.art.add(A+'/0 New.flac')
assert m.folder(A+'/00 Zero.flac')==0 and m.tried==[]  # the same walk: not listed again, the first not tried twice
assert m.folder(A+'/04 Four.flac')==1 and m.tried==[A+'/04 Four.flac']
assert m.folder(A+'/05 Five.flac')==1 and m.tried==[A+'/0 New.flac']
m.art={'/mnt/mmc/Other/9.flac'}
assert m.folder('/mnt/mmc/Other/9.flac')==1 and m.tried==['/mnt/mmc/Other/9.flac']  # no listing: stock's song
passed()

textures=[cover_pixels(100+j) for j in range(7)]
cases=[(0,127),(16384,127),(-16384,127),(32767,127),(-32768,127),(5000,0b0111110),(0,0)]
want=host_render(textures,cases)
m=DepthMachine(); tex=m.big_alloc(7*160*160*4); m.u.mem_write(tex,b''.join(textures))
ring=m.big_alloc(60)+16; frame=m.big_alloc(4*O['CF_VIEW_W']*O['CF_VIEW_H'])  # a thumb theme's ring reaches 4 more each way
for (frac,mask),host in zip(cases,want):
    for k in range(7): m.word(ring+4*k,tex+k*160*160*4 if mask>>k&1 else 0)
    m.call(address=ps['coverflow_render'],args=(frame,O['CF_VIEW_W'],frac,ring),gap=0,count=50_000_000)
    assert bytes(m.u.mem_read(frame,len(host)))==host,(frac,mask)
    passed()

# On the page: the slide_menu spans the frame at CF_STRIDE per album, its children stay empty, and a
# paint of it draws the frame 1:1 at its origin, marked opaque; the covers around the position are
# decoded once, each load dropped at once. What is drawn is what the renderer draws for that ring.
m=DepthMachine(); page=m.open(); s=m.slide
assert len(m.frames)==1 and cf_geometry(m,s)==(0,0,O['CF_VIEW_W'],O['CF_VIEW_H'])
stride=signed(m.get(s+O['SLIDE_SPACER']))+O['CF_VIEW_H']; assert stride==O['CF_STRIDE']
assert all('image' not in m.nodes[c] for c in m.nodes[s]['children'])
def paint(m):
    return m.call(address=HOOKS['widget_on_paint_border'][0],args=(m.slide,m.canvas,0,0),gap=0,clear=False,count=50_000_000)
instructions=[0]
def count_block(u,address,size,unused): instructions[0]+=size//4
counter=m.u.hook_add(UC_HOOK_BLOCK,count_block,begin=BASE,end=SCRATCH-1)
paint(m); rest_cost=instructions[0]
assert len(m.draws)==1 and m.draws[0][1]==m.frames[0] and m.draws[0][2]==m.draws[0][3]==(0,0,O['CF_VIEW_W'],O['CF_VIEW_H'])
assert m.draws[0][4]&1  # BITMAP_FLAG_OPAQUE
assert struct.unpack('<H',bytes(m.u.mem_read(m.frames[0]+0xe,2)))[0]==O['LCD_BGRA8888']  # the screen's format: stock copies it, not blends
# The placeholder first (fx_open), then the ring round album 0 of three, nearest first, which repeats as
# the slide_menu wraps: 0, 1, 2, 0, 1, 2, 0 from -3, each album decoded once.
assert len(m.loads)==4 and m.loads[0]=='default_album_flow' and all(u.startswith('file://') for u in m.loads[1:]) and m.unloads==3
tex_of={u:columns(bytes(m.u.mem_read(m.pixels[u],160*160*4))) for u in m.pixels}  # 160 square: decoded as they are, by columns
ring_tex=[tex_of[m.loads[1+(i+2)%3]] for i in range(15)]  # its wide ring: album i - 7
assert host_render(ring_tex,[(0,(1<<15)-1)],still=True)[0]==m.draws[0][5]; passed()
# Classic's shelf on the page, both halves: its own frame height, its stride kept, drawn 1:1 from
# the payload as the host renders it, on the scheme's paper; Classic's own frame stays as it was.
cl_style={k:v for k,v in next(t for t in theme_builtins() if t['id']=='classic-light').items() if k.startswith('cf.')}
for light,paper in (('0',0),('1',0xff)):
    SETUP[:]=[lambda k:(k.config.update(THEME='1',LIGHT=light),k)]; c=DepthMachine(); SETUP.clear()
    view,c.imgs=home_list(c); c.img=c.imgs[2]; c.home=c.top; c.stack=[c.top]  # as open(), from the row's own click: no list painted
    assert c.call(address=home_hook[0],args=(c.top,0,0,0),gap=0)==0
    f,ctx=c.handler(c.img,O['EVT_CLICK']); assert c.call(address=f,args=(ctx,c.event,0,0),gap=0)==0
    c.page=c.top; c.slide=cs=c.find('slide_menu'); assert cf_geometry(c,cs)==(0,0,O['CF_VIEW_W'],cl_style['cf.view_h'])
    assert signed(c.get(cs+O['SLIDE_SPACER']))+cl_style['cf.view_h']==cl_style['cf.stride']
    paint(c); assert c.draws[0][2]==c.draws[0][3]==(0,0,O['CF_VIEW_W'],cl_style['cf.view_h'])
    frame_bytes=c.draws[0][5]; assert frame_bytes[0:3]==bytes([paper])*3
    c_tex={u:columns(bytes(c.u.mem_read(c.pixels[u],160*160*4))) for u in c.pixels}  # its ring of 15 loads nearest first: album 0, 1, 2
    assert host_render([c_tex[c.loads[1+(i+2)%3]] for i in range(15)],[(0,(1<<15)-1)],{**cl_style,'cf.radius':0},paper=0xffffff if light=='1' else None,still=True)[0]==frame_bytes  # square art
    passed()
# ... and mid-step, along coverflow.shelf.swing's path: the payload's arithmetic, the host's frames.
