m.word(s+O['SLIDE_INDEX'],2); f,ctx=m.handler(s,O['EVT_VALUE_CHANGED']); m.call(address=f,args=(ctx,m.event,0,0),gap=0)
assert m.nodes[info]['visible'] and m.nodes[info]['text']=="Can't open this photo"; passed()
