f,ctx=m.handler(m.rows()[1],O['EVT_CLICK']); m.call(address=f,args=(ctx,m.event,0,0),gap=0)
m.serve=lambda op,args: (*OK,jobs[:1]); worker,arg=m.threads[-1]
